-- purge returned: Delete the returned loans
-- Changes exactly 4 Loan records of table loans: sets is_deleted to true, where status == "returned".
-- Dry run: mariadb --init-command="SET @last_modified_by_user_id = '...', @last_modified_by_user_nameid = '...'" <database> < purge-returned.sql
-- Apply: the same with @apply = true in the SET. Without it every check runs against the data and the change is rolled back.
SET SESSION sql_mode = CONCAT_WS(',', NULLIF(REPLACE(@@SESSION.sql_mode, 'NO_BACKSLASH_ESCAPES', ''), ''), 'STRICT_ALL_TABLES');
DELIMITER //
BEGIN NOT ATOMIC
  DECLARE found BIGINT;
  DECLARE changed BIGINT;
  DECLARE refusal TEXT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  -- The variables: each is set, and its text is a value of its column.
  IF @apply IS NOT NULL AND NOT LOWER(@apply) IN ('true', 'false', '1', '0') THEN
    SET refusal = CONCAT('purge-returned.sql: the variable @apply is ', QUOTE(@apply), ', which is not true or false; nothing was read');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = refusal;
  END IF;
  IF @last_modified_by_user_id IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'purge-returned.sql: the variable @last_modified_by_user_id is not set; give it as SET @last_modified_by_user_id = ''<last_modified_by_user_id>'' (VARCHAR(255)) in --init-command';
  END IF;
  IF @last_modified_by_user_nameid IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'purge-returned.sql: the variable @last_modified_by_user_nameid is not set; give it as SET @last_modified_by_user_nameid = ''<last_modified_by_user_nameid>'' (VARCHAR(255)) in --init-command';
  END IF;
  START TRANSACTION;
  script: BEGIN
    -- 1. Precondition: exactly 4 Loan records to change, locked until the end.
    SELECT COUNT(*) INTO found FROM loans
      WHERE (status = 'returned')
        AND is_deleted = false
      FOR UPDATE;
    IF found <> 4 THEN
      SET refusal = CONCAT('command purge returned: ', found, ' Loan records hold status == "returned", not deleted, and the change expects exactly 4; nothing was changed');
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = refusal;
    END IF;
    -- 2. The change, under the same condition.
    UPDATE loans
      SET is_deleted = true,
        last_modified_at = DATE_FORMAT(UTC_TIMESTAMP(6), '%Y-%m-%dT%H:%i:%s.%f000Z'),
        last_modified_by_user_id = CAST(@last_modified_by_user_id AS CHAR),
        last_modified_by_user_nameid = CAST(@last_modified_by_user_nameid AS CHAR)
      WHERE (status = 'returned')
        AND is_deleted = false;
    SET changed = ROW_COUNT();
    -- 3. Postcondition: the exact count.
    IF changed <> 4 THEN
      SET refusal = CONCAT('command purge returned: the change wrote ', changed, ' Loan records, and exactly 4 was expected; another writer may have changed them after they were counted; nothing was changed');
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = refusal;
    END IF;
    -- 4. Dry run unless apply is true.
    IF LOWER(@apply) IN ('true', '1') THEN
      SELECT 'command purge returned: 4 Loan records changed; committing' AS message;
      COMMIT;
    ELSE
      SELECT 'command purge returned: dry run: 4 Loan records would change, and every check passed; rolling back. Run it again with @apply = true to make the change' AS message;
      ROLLBACK;
    END IF;
  END script;
END//
DELIMITER ;
